# Writing Section 1 of the packet — the contract, field by field
#
# Mission: Take one real (or realistic) service on your write→read path and write an Instrumentation Contract: the exact metric names, required label keys, units, cardinality budget, and trace span attributes it MUST emit — versioned, so every dashboard, SLO, and alert downstream can be built against a fixed schema instead of whatever a developer happened to log.
#
# Evidence checklist:
# 1. Trace/metric proof: run the actual SLO query against emitted telemetry and confirm it returns series (not an empty result that masquerades as 'healthy'). Screenshot-note the p99 value.
# 2. Unit check: every duration metric carries its unit in the name AND the SLO math assumes that unit — no seconds/ms mismatch.
# 3. Cardinality proof: for each required label, state its bound and confirm no label (especially anything user-derived) is unbounded; compute worst-case series count.
# 4. Enforcement proof: the CI contract-check exists and you have seen it FAIL on a deliberate drift (rename a metric, watch the build go red), then pass when reverted.
# 5. Alert threshold decision: record the burn-rate threshold you chose for the availability SLO and why — a specific number, defensible in an incident review, not 'alert when it looks bad'.
#
# Work only in the TODO function. Run every fixture and compare every output line.
# Local execution is practice feedback; it does not create controlled mastery evidence.

CONTRACT = {
    "http_request_duration_seconds": {
        "route": 5, "method": 4, "status_class": 3,
    },
    "orders_created_total": {"payment_kind": 4},
}

EMISSIONS = []
for i in range(200):
    EMISSIONS.append(("http_request_duration_seconds", {
        "route": f"/orders/{i}" if i % 3 == 0 else "/orders",
        "method": "GET" if i % 2 else "POST",
        "status_class": "2xx" if i % 19 else "5xx",
    }))
for i in range(40):
    labels = {"payment_kind": "card" if i % 2 else "wallet"}
    if i % 8 == 5:
        labels.pop("payment_kind")
    EMISSIONS.append(("orders_created_total", labels))
for i in range(10):
    EMISSIONS.append(("request_latency_ms", {"route": "/orders"}))


def check_emissions(contract, emissions):
    # TODO: implement the evidence decision from the supplied telemetry fixtures.
    # Preserve failure discrimination and the exact observable contract.
    raise NotImplementedError("complete the observability decision")

violations = check_emissions(CONTRACT, EMISSIONS)
for v in violations:
    print(f"VIOLATION {v}")
print(f"contract check: {len(violations)} violation(s) -> {'BUILD FAILED' if violations else 'BUILD OK'}")

