// SLO source of truth — imported by BOTH the dashboard and the alert rule.
local slo = import 'slo/checkout.libsonnet';
// slo.latency_p99_ms == 800  (the number a reviewer can grep in one place)

local panel = {
  title: 'Checkout p99 latency vs SLO',
  type: 'timeseries',
  targets: [{
    // Query the same metric the error budget burns on.
    expr: 'histogram_quantile(0.99, sum by (le) (rate(http_request_duration_seconds_bucket{job="checkout"}[5m]))) * 1000',
    legendFormat: 'p99 (ms)',
  }],
  // The red line is the SLO, not a magic number typed into the UI.
  thresholds: { steps: [
    { color: 'green', value: null },
    { color: 'red', value: slo.latency_p99_ms },
  ] },
};

{
  title: 'Checkout · Latency SLO',
  uid: 'checkout-latency',      // stable uid → idempotent re-apply, no dupes
  editable: false,             // provisioning-locked: no hand-edits in prod
  panels: [panel { gridPos: { h: 8, w: 12, x: 0, y: 0 } }],
}

