    "checkout p99 vs SLO": {
        "query": 'p99(http_request_duration_seconds{route="/checkout"})',
        "threshold_ms": 1000,
    },
    "error rate": {
        "query": 'rate(http_5xx{route="/checkout"})',
        "threshold_ms": 5,
    },
    "host cpu (vanity)": {
        "query": "avg(node_cpu_utilization)",
        "threshold_ms": 85,
    },
}

